package io.github.sen2maker.buildingwebviewer;
import org.junit.Test;import static org.junit.Assert.*;
public class NativeGaussianNavigationTest {
 static float dot(float[] a,float[] b){return a[0]*b[0]+a[1]*b[1]+a[2]*b[2];}
 @Test public void cameraAxesRemainDistinctAtEveryPitchAndHeading(){for(float elevation:new float[]{-89,-35,0,38,85,90})for(float heading:new float[]{0,90,180,-90,35}){float[][] basis=NativeGaussianNavigation.basis(elevation,heading);float[] f=NativeGaussianNavigation.direction(basis,0,1,0),u=NativeGaussianNavigation.direction(basis,0,0,1),r=NativeGaussianNavigation.direction(basis,1,0,0);assertEquals(-1,dot(f,basis[2]),.00001);assertEquals(0,dot(f,basis[1]),.00001);assertEquals(1,dot(u,basis[1]),.00001);assertEquals(0,dot(u,basis[2]),.00001);assertEquals(1,dot(r,basis[0]),.00001);assertEquals(0,dot(f,u),.00001);}}
 @Test public void oppositeInputsAndDiagonalSpeed(){float[][] basis=NativeGaussianNavigation.basis(85,35);float[] forward=NativeGaussianNavigation.direction(basis,0,1,0),back=NativeGaussianNavigation.direction(basis,0,-1,0);for(int a=0;a<3;a++)assertEquals(-forward[a],back[a],.00001);float[] combined=NativeGaussianNavigation.direction(basis,1,1,1);assertEquals(1,Math.sqrt(dot(combined,combined)),.00001);assertEquals(0,NativeGaussianNavigation.clamp(Float.NaN),0);}
 @Test public void localYawAndPitchWorkAtPolesWithoutUnwantedRoll(){for(float elevation:new float[]{-90,-85,0,38,85,90})for(float roll:new float[]{-80,0,65}){float[][] old=NativeGaussianNavigation.rolledBasis(elevation,-55,roll);float[][] yaw=NativeGaussianNavigation.look(old,10,0,0),pitch=NativeGaussianNavigation.look(old,0,10,0);assertEquals(1,dot(yaw[1],old[1]),.00001);assertTrue(dot(yaw[2],old[0])<-.17);assertEquals(1,dot(pitch[0],old[0]),.00001);assertTrue(dot(pitch[2],old[1])<-.17);float[] angles=NativeGaussianNavigation.angles(yaw,-55);float[][] back=NativeGaussianNavigation.rolledBasis(angles[0],angles[1],angles[2]);for(int a=0;a<3;a++)assertArrayEquals(yaw[a],back[a],.00001f);}}
 @Test public void leanPreservesHeadingAndHasDistinctAxis(){float[][] old=NativeGaussianNavigation.rolledBasis(85,-55,30),lean=NativeGaussianNavigation.look(old,0,0,20);assertArrayEquals(old[2],lean[2],.000001f);assertTrue(dot(lean[0],old[1])<-.34);assertTrue(dot(lean[1],old[0])>.34);}
 @Test public void fasterDefaultMigratesWithoutOverwritingCustomSensitivity(){assertEquals(1,NativeGaussianNavigation.sensitivity(.3,1),0);assertEquals(.5f,NativeGaussianNavigation.sensitivity(.5,1),0);assertEquals(.3f,NativeGaussianNavigation.sensitivity(.3,2),0);assertEquals(1,NativeGaussianNavigation.sensitivity(Double.NaN,1),0);}

}
